LAYER
  NAME "capa_poblacion_veracruz"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, poblacion FROM marco_geoestadistico.poblacion) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Población total del estado de Veracruz"
    "wms_enable_request" "*"
  END
